// Isolated projection scheduling experiment. No original headers are edited.
#include "symrep_io.hpp"
#include "projection.hpp"
#include "projection_residual_certificate.hpp"
using namespace symrep;
static double seconds(std::chrono::steady_clock::time_point x){return std::chrono::duration<double>(std::chrono::steady_clock::now()-x).count();}
struct DenseRow {
 std::vector<Q>a;std::vector<unsigned char>seen;std::vector<size_t>touched;
 explicit DenseRow(size_t n):a(n),seen(n){}
 void add(size_t i,const Q&x,const Q&y){if(!seen[i]){seen[i]=1;touched.push_back(i);}a[i]+=x*y;}
 void clear(){for(auto i:touched){a[i]=0;seen[i]=0;}touched.clear();}
 Vec pack(){std::sort(touched.begin(),touched.end());Vec v;for(auto i:touched)if(a[i]!=0)v.push_back(index(i),a[i]);return v;}
};
static Mat contract_cfirst(const Tensor&A,const Mat&B,const Mat&C){require(A.rank()==3&&A.dim(1)==B.nrow&&A.dim(2)==C.nrow,"axis dimensions");size_t q=C.ncol;Mat D(A.dim(0),B.ncol*q);DenseRow early(B.nrow*q),late(B.ncol*q);size_t first_nnz=0;auto start=std::chrono::steady_clock::now();
 for(size_t r=0;r<A.dim(0);++r){for(size_t k=A.rowptr()[r];k<A.rowptr()[r+1];++k){auto idx=A.index(k);for(auto[t,y]:C[idx[1]])early.add(size_t(idx[0])*q+t,A.val(k),y);}for(auto j:early.touched)if(early.a[j]!=0){++first_nnz;size_t p=j/q,t=j%q;for(auto[d,y]:B[p])late.add(size_t(d)*q+t,early.a[j],y);}D[r]=late.pack();early.clear();late.clear();if((r+1)%4096==0)std::cout<<"CFIRST_PROGRESS rows="<<r+1<<" first_nnz="<<first_nnz<<" output_nnz="<<D.nnz()<<" seconds="<<seconds(start)<<std::endl;}
 std::cout<<"CFIRST_CONTRACTION rows="<<D.nrow<<" cols="<<D.ncol<<" first_nnz="<<first_nnz<<" output_nnz="<<D.nnz()<<" seconds="<<seconds(start)<<std::endl;return D;}
int main(int argc,char**argv){try{require(argc==6||argc==7,"usage projection_cfirst BOUNDARY weight bfirst|cfirst OUTPUTSTEM full|contract [reference_directory]");fs::path dir=argv[1],stem=argv[4];size_t w=std::stoul(argv[2]);bool cf=std::string(argv[3])=="cfirst",full=std::string(argv[5])=="full";rref_option_t opt;opt->pool.reset(1);auto start=std::chrono::steady_clock::now();auto A=read(dir/("FEC_"+std::to_string(w)+".wxf")),Bt=read(dir/"collinear"/("first_w"+std::to_string(w-1)+".wxf")),Ct=read(dir/"data/colmat42.wxf");size_t nr=A.dim(0),nd=Bt.dim(1),q=Ct.dim(1);std::cout<<"INPUT rows="<<nr<<" old="<<A.dim(1)<<" new="<<nd<<" letters="<<q<<" A_nnz="<<A.nnz()<<" B_nnz="<<Bt.nnz()<<" C_nnz="<<Ct.nnz()<<" seconds="<<seconds(start)<<std::endl;
 if(!cf&&full){auto result=compute_stage1_projection(std::move(A),std::move(Bt),std::move(Ct),true,QQ,opt);write(stem.string()+"_projection.wxf",result.projection);write(stem.string()+"_basis.wxf",result.basis);std::cout<<"BFIRST_FULL seconds="<<seconds(start)<<std::endl;return 0;}
 Mat D;if(cf){auto B=flatten(Bt),C=flatten(Ct);Bt.clear();Ct.clear();D=contract_cfirst(A,B,C);A.clear();}else{auto d=tenary_contract(SparseRREF::sparse_tensor<Q,I,SPARSE_COO>(std::move(A)),SparseRREF::sparse_tensor<Q,I,SPARSE_COO>(std::move(Bt)),SparseRREF::sparse_tensor<Q,I,SPARSE_COO>(std::move(Ct)),QQ,&opt->pool);D=flatten(Tensor(std::move(d),&opt->pool));}
 if(!full){write(stem.string()+"_contract.wxf",D);std::cout<<"CONTRACT_DONE seconds="<<seconds(start)<<std::endl;return 0;}
 if(w>=6){write_tensor_view(stem.string()+"_contract.wxf",MatrixTensorView(D,{D.nrow,D.ncol}));std::cout<<"CONTRACTION_CHECKPOINT_SAVED seconds="<<seconds(start)<<std::endl;}
 auto tick=std::chrono::steady_clock::now();auto rr=D;auto piv=sparse_mat_rref_reconstruct(rr,opt);std::vector<I>pivot(rr.nrow,-1);size_t rank=0;for(auto&batch:piv)for(auto[r,c]:batch){pivot[r]=c;++rank;}Mat basis(rank,D.ncol);std::vector<I>which(D.ncol,-1);size_t j=0;for(size_t r=0;r<rr.nrow;++r)if(rr[r].nnz()){require(pivot[r]>=0,"nonzero nonpivot RREF row");which[pivot[r]]=index(j);basis[j++]=std::move(rr[r]);}rr.clear();require(j==rank,"rank count");for(size_t r=0;r<rank;++r)for(auto[c,x]:basis[r])if(which[c]>=0)require(which[c]==index(r)&&x==1,"RREF pivot block identity");Mat P(nr,rank);for(size_t r=0;r<nr;++r)for(auto[c,x]:D[r])if(which[c]>=0)P[r].push_back(which[c],x);for(auto&row:P.rows)normalize(row);std::cout<<"CFIRST_RREF rank="<<rank<<" basis_nnz="<<basis.nnz()<<" projection_nnz="<<P.nnz()<<" seconds="<<seconds(tick)<<std::endl;
 write_tensor_view(stem.string()+"_projection.wxf",MatrixTensorView(P,{P.nrow,P.ncol}));write_tensor_view(stem.string()+"_basis.wxf",MatrixTensorView(basis,{rank,nd,q}));{std::ofstream pending(stem.string()+".pending.json");pending<<"{\"state\":\"RREF and coordinate checkpoints saved; full exact projection certificate pending\",\"image_dimension\":"<<rank<<"}\n";}std::cout<<"RREF_CHECKPOINTS_SAVED seconds="<<seconds(start)<<std::endl;
 tick=std::chrono::steady_clock::now();auto certificate=projection_certificate::certify(D,P,basis);D.clear();std::cout<<"CFIRST_FULL_CERTIFICATE all_rows="<<nr<<" exact_pass=1 primes="<<certificate.primes<<" seconds="<<seconds(tick)<<std::endl;
 if(argc==7){fs::path ref=argv[6];require(equal(P,read_matrix(ref/("first_w"+std::to_string(w)+".wxf"))),"reference projection differs");require(equal(basis,flatten(read(ref/("first_w"+std::to_string(w)+"_basis.wxf")))),"reference basis differs");std::cout<<"REFERENCE_COMPLETE_OUTPUT_EQUALITY pass=1\n";}
 std::ofstream receipt(stem.string()+".json");receipt<<"{\"all_checks_pass\":true,\"weight\":"<<w<<",\"boundary_alphabet_size\":"<<q<<",\"input_dimension\":"<<nr<<",\"image_dimension\":"<<rank<<",\"full_exact_projection_residual\":true,\"full_reference_output_equality\":"<<(argc==7?"true":"null")<<",\"all_spurious_directions_retained\":true,\"finite_targets_read\":false,\"certificate_primes\":"<<certificate.primes<<",\"certificate_modulus\":\""<<certificate.modulus<<"\",\"certificate_integer_bound\":\""<<certificate.bound<<"\",\"method\":\"per-row C-first sparse accumulation; complete rational RREF; direct pivot-coordinate projection; full modular D=P.basis residual with a proven denominator/height bound establishing exact equality\",\"seconds\":"<<seconds(start)<<"}\n";std::cout<<"COMPLETE seconds="<<seconds(start)<<std::endl;
}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}return 0;}
